/*
    Analytic fit of the AgX default contrast transfer function:
    https://github.com/sobotka/AgX/blob/main/LUTs/AgX_Default_Contrast.spi1d
*/

float AgX_tf(float x)
{
    bool u = x >= 0.61376220703125;

    float k = u ? 1.2275244140625 - x : x;

   #if 1
    // min rel err
    float a = (0.7823   - 0.150163 * k) * k;
    float b =  0.735882 - 1.19897  * k;
   #else
    // min abs err
    float a = (0.77085           - 0.1               * k) * k;
    float b =  0.736149499672221 - 1.199405064761082 * k;
   #endif

    float ab = (a * b) * inversesqrt(a*a + b*b);

    return 0.8402324908443617 * x + ab * (u ? 1.0 : -1.0);
}

vec3 AgX_tf(vec3 x)
{
    return vec3(AgX_tf(x.r), 
                AgX_tf(x.g), 
                AgX_tf(x.b));
}

// polynomial fit (~1.33x faster)
vec3 AgX_tfB(vec3 x)
{
    x = (((2.3756 * x - 3.5265) * x + 0.4727) * x - 0.218  ) * x + 0.5815  ;
    x = (((1.7907 * x + 0.6957) * x - 1.0095) * x - 1.23219) * x + 0.716327;

    return x;
}

void mainImage( out vec4 outCol, in vec2 uv0 )
{
	vec2 uv = uv0 - 0.5;

    vec2 tex = uv0;
    tex -= iResolution.xy * 0.125;
    tex /= iResolution.xx * 0.125;

    tex *= 0.25+0.0375;

    vec3 col = vec3(0.0);

	col = mix(vec3(1.0), vec3(0.9), Grid(tex.xy * 4.0, 0.0));        
	col = mix(col, vec3(0.5), Grid(tex.xy * 1.0, 0.0));        
	col = mix(col, vec3(0.125), Cross(tex.xy * 1.0, 0.)); 	

    // AgX default contrast transfer function
   #if 1
    col = mix(col, vec3(0.0, 0.0, 0.0), 0.90*Graph(AgX_tf (tex.xxx).r - tex.y, 0.5));
   #else
    col = mix(col, vec3(0.0, 0.0, 0.0), 0.90*Graph(AgX_tfB(tex.xxx).r - tex.y, 0.5));    
   #endif

   #if 1
    vec2 s = (uv0/iResolution.xy*2.0-1.0);
    s.x = 1.0-Pow2(s.x);    s.y = 1.0-Pow2(s.y);
    col *= mix(1.0, 0.4, Pow2(1.0-sqrt(s.x*s.y)));
   #endif

    outCol = vec4(GammaEncode(clamp01(col)), 1.0);    

}



